INSERT INTO `js_cms_site` VALUES ('main','JeeSite',1,'JeeSite 快速开发平台','','','JeeSite','JeeSite 快速开发平台，不仅仅是一个后台开发框架，它是一个企业级快速开发解决方案，后端基于经典组合 Spring Boot、Shiro、MyBatis，前端采用 Beetl、Bootstrap、AdminLTE 经典开发模式，或者分离版 Vue3、Vite、Ant Design Vue、TypeScript、Vben Admin 最先进技术栈。提供在线代码生成功能，支持 Spring Cloud 架构，分布式，微服务，微内核，信息化领域的专家。','default','<!--HTML--><p>Copyright © 2024 演示站 - Powered By JeeSite V5</p>','index','0','system','2024-12-13 11:40:29','system','2024-12-13 11:40:29',NULL),('sub1','子站点',2,'子站点演示','','','JeeSite','','default','<!--HTML--><p>子站点样式</p>','index','0','system','2024-12-13 11:40:29','system','2024-12-13 11:40:29',NULL);
/*!40000 ALTER TABLE `js_cms_site` ENABLE KEYS */;
