--
-- Table structure for table `js_dbm_table`
--

DROP TABLE IF EXISTS `js_dbm_table`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `js_dbm_table` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '编号',
  `ds_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '数据源编码',
  `ds_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '数据源名称',
  `module_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '归属模块',
  `category_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类编码',
  `category_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类名称',
  `table_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '数据表名',
  `table_comment` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '数据表描述',
  `is_sys` char(1) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '是否系统',
  `options` text COLLATE utf8mb4_unicode_ci COMMENT '其它选项',
  `status` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '状态（0正常 1删除 2停用）',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注信息',
  `corp_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '租户代码',
  `corp_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'JeeSite' COMMENT '租户名称',
  PRIMARY KEY (`id`),
  KEY `idx_dbm_table_dc` (`ds_code`),
  KEY `idx_dbm_table_tc` (`category_code`),
  KEY `idx_dbm_table_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='数据表定义';
