--
-- Table structure for table `js_dbm_table_index`
--

DROP TABLE IF EXISTS `js_dbm_table_index`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `js_dbm_table_index` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '编号',
  `table_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表编号',
  `index_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '索引名称',
  `index_columns` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '索引列名',
  `index_comments` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '索引描述',
  `index_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '索引类型',
  `status` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '状态（0正常 1删除 2停用）',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注信息',
  `corp_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '租户代码',
  `corp_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'JeeSite' COMMENT '租户名称',
  PRIMARY KEY (`id`),
  KEY `idx_dbm_table_idx_ti` (`table_id`),
  KEY `idx_dbm_table_idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='数据表索引';
/*!40101 SET character_set_client = @saved_cs_client */;

